<script setup>
import anime from 'animejs'
import { nextTick, onMounted, ref } from 'vue'

const props = defineProps({
  size:    { type: Number, default: 240 },
  color:   { type: String, default: 'var(--c-siger)' },
  opacity: { type: Number, default: 1 },
  delay:   { type: Number, default: 0 },
  autoplay:{ type: Boolean, default: true },
  trigger: { type: String, default: 'visible' }, // 'visible' atau 'load'
})

const wrapEl  = ref(null)
const pathEl  = ref(null)
const fillOpacity = ref(0)

function runTrace() {
  if (!pathEl.value) return
  const len = pathEl.value.getTotalLength()
  pathEl.value.style.strokeDasharray  = len
  pathEl.value.style.strokeDashoffset = len

  anime.timeline({ easing: 'easeInOutSine' })
    .add({
      targets: pathEl.value,
      strokeDashoffset: [len, 0],
      duration: 2200,
      delay: props.delay,
    })
    .add({
      targets: fillOpacity,
      value: 0.25,
      duration: 800,
    }, '-=600')
}

onMounted(async () => {
  await nextTick()
  if (!props.autoplay || !wrapEl.value) return

  if (props.trigger === 'load') {
    runTrace()
  } else {
    const obs = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (!e.isIntersecting) return
        obs.unobserve(e.target)
        runTrace()
      })
    }, { threshold: 0.1 })
    obs.observe(wrapEl.value)
  }
})

defineExpose({ runTrace })
</script>

<style scoped>
.siger-wrap { display: inline-block; line-height: 0; }
.siger-path { stroke-dasharray: 99999; stroke-dashoffset: 99999; }
</style>
